def compute(vars):
    numerator = vars["v1"]
    denominator = vars["v2"]

    if denominator == 0:
        return None

    ratio = numerator / denominator
    percentage = round(ratio * 100, 3)

    return {
        "value": percentage,
        "trace": {
            "numerator": numerator,
            "denominator": denominator,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
